package services

// PhpMyAdminUserConfig is the user-owned phpMyAdmin configuration seeded on
// install and activate. It targets the fixed "db" Compose network alias so
// login works on native Linux and Windows/WSL, where the host-gateway address
// cannot reach the loopback-published MySQL port. UploadDir and SaveDir are
// cleared because the container has no operator-managed upload directory.
const PhpMyAdminUserConfig = `<?php
// Generated by devstack as a safe starting point.
// This file is user-owned after the first install; devstack never overwrites it.
// "db" is the fixed Compose network alias for the active MySQL-family service.
$cfg['UploadDir'] = '';
$cfg['SaveDir'] = '';
$cfg['Servers'][1]['host'] = 'db';
$cfg['Servers'][1]['port'] = '3306';
$cfg['Servers'][1]['auth_type'] = 'cookie';
`
